def segundo_maior(lista):
    lista = list(set(lista))
    if len(lista) < 2:
        return None
    lista.sort(reverse=True)
    return lista[1]

def agrupa_por_tamanho(palavras):
    result = {}
    for palavra in palavras:
        tamanho = len(palavra)
        if tamanho not in result:
            result[tamanho] = []
        result[tamanho].append(palavra)
    return result

